# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MUHATABI İKNA EDEN KONUŞMA TASARIMI VE SÖYLEYİŞ İNCELİKLERİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KONUŞMA İÇERİĞİNİ PLANLAMA (TDE3.2)</text>\n  <text x="38" y="90" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Amaç ve Hedef Kitle Analizi:</text>\n  <text x="46" y="106" font-size="11" fill="#1d4ed8">Dinleyicinin yaş, ilgi ve beklentilerine göre</text>\n  <text x="46" y="122" font-size="11" fill="#1d4ed8">giriş, gelişme ve sonuç bölümlerini tasarlama.</text>\n  <text x="38" y="144" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Kullanım Alanı ve Söz Varlığı:</text>\n  <text x="46" y="160" font-size="11" fill="#1d4ed8">Özel, mesleki, kamusal veya eğitim alanına uygun</text>\n  <text x="46" y="176" font-size="11" fill="#1d4ed8">üslup, deyim, atasözü ve edebî sanat seçimi.</text>\n  <text x="38" y="198" font-size="11.5" font-weight="bold" fill="#1e3a8a">3. İkna Üçgeni (Retorik Unsurlar):</text>\n  <text x="46" y="216" font-size="11" font-weight="bold" fill="#2563eb">Ethos (Güvenilirlik) + Pathos (Duygu) + Logos (Mantık/Kanıt)</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">DİLİN İŞLEVLERİ VE İLETİ TÜRLERİ</text>\n  <text x="370" y="90" font-size="11.5" fill="#78350f">• Alıcıyı Harekete Geçirme İşlevi: Muhatabı ikna</text>\n  <text x="378" y="106" font-size="11" fill="#92400e">etme, tutum ve davranış değişikliği oluşturma.</text>\n  <text x="370" y="128" font-size="11.5" fill="#78350f">• Göndergesel İşlev: Nesnel bilgi ve kanıt sunma.</text>\n  <text x="370" y="150" font-size="11.5" fill="#78350f">• Heyecana Bağlı &amp; Şiirsel İşlev: Duygu ve estetik</text>\n  <text x="378" y="166" font-size="11" fill="#92400e">söyleyiş inceliğiyle dinleyiciyi etkileme.</text>\n  <rect x="370" y="178" width="290" height="50" rx="6" fill="#ffedd5" stroke="#f59e0b"/>\n  <text x="515" y="197" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Açık ve Örtük İletiler:</text>\n  <text x="515" y="214" text-anchor="middle" font-size="11" fill="#7c2d12">Doğrudan söylenen (açık) ve sezdirilen/ima edilen (örtük) anlam.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜŞÜNCEYİ GELİŞTİRME YOLLARI VE İYİ BİR ANLATIMIN NİTELİKLERİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">DÜŞÜNCEYİ GELİŞTİRME YOLLARI (İKNA)</text>\n  <text x="38" y="92" font-size="11.5" fill="#14532d">• Tanımlama: \'Sözün inceliği, kalbe dokunan dildir.\'</text>\n  <text x="38" y="114" font-size="11.5" font-weight="bold" fill="#15803d">• Karşılaştırma: İki kavram/durum arasındaki</text>\n  <text x="46" y="130" font-size="11" fill="#166534">benzerlik ve farklılıkları ortaya koyma.</text>\n  <text x="38" y="152" font-size="11.5" fill="#14532d">• Örneklendirme: Soyut fikri somut örneklerle açma.</text>\n  <text x="38" y="174" font-size="11.5" font-weight="bold" fill="#15803d">• Tanık Gösterme: Uzman/bilge bir kişinin sözünü</text>\n  <text x="46" y="190" font-size="11" fill="#166534">alıntılama (Yunus Emre\'nin \'Söz ola kese savaşı\' sözü).</text>\n  <text x="38" y="212" font-size="11.5" fill="#14532d">• Sayısal Verilerden Yararlanma ve Benzetme.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">ANLATIMIN TEMEL İLKELERİ VE BAĞDAŞIKLIK</text>\n  <text x="370" y="90" font-size="11.5" fill="#581c87">• Açıklık: Anlamın net olması, bulanıklık olmaması.</text>\n  <text x="370" y="112" font-size="11.5" fill="#581c87">• Duruluk: Gereksiz sözcük bulunmaması (ekonomi).</text>\n  <text x="370" y="134" font-size="11.5" fill="#581c87">• Yalınlık (Sadelik): Yapmacık ve ağır süsten uzaklık.</text>\n  <text x="370" y="156" font-size="11.5" fill="#581c87">• Akıcılık: Ses ve söyleyiş pürüzü bulunmaması.</text>\n  <text x="370" y="178" font-size="11.5" fill="#581c87">• Özgünlük &amp; Özlülük: Kendine has üslup; az sözle çok anlam.</text>\n  <rect x="370" y="190" width="290" height="40" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="515" y="207" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Bağdaşıklık (Dil Bilgisel Bağlar) &amp; Bağlaşıklık (Tutarlılık):</text>\n  <text x="515" y="222" text-anchor="middle" font-size="10.5" fill="#581c87">ama, çünkü, buna karşılık, özetle, dolayısıyla gibi geçişler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KONUŞMADA SES, DİKSİYON, BEDEN DİLİ VE DEĞERLENDİRME (TDE3.3 - 3.4)</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">SESLETİM, DİKSİYON VE BEDEN DİLİ</text>\n  <text x="40" y="92" font-size="11.5" font-weight="bold" fill="#7c2d12">• Diksiyon ve Telaffuz (Boğumlama):</text>\n  <text x="48" y="108" font-size="11" fill="#9a3412">Sesleri, heceleri ve kelimeleri doğru boğumlama;</text>\n  <text x="48" y="124" font-size="11" fill="#9a3412">vurgu, tonlama ve durakları anlama uygun kullanma.</text>\n  <text x="40" y="148" font-size="11.5" font-weight="bold" fill="#7c2d12">• Beden Dili ve Mekân Kullanımı:</text>\n  <text x="48" y="164" font-size="11" fill="#9a3412">Göz teması kurma, abartısız jest (el-kol) ve mimik</text>\n  <text x="48" y="180" font-size="11" fill="#9a3412">(yüz) hareketleri, dik duruş, zaman ve mekân yönetimi.</text>\n  <text x="40" y="204" font-size="11.5" font-weight="bold" fill="#c2410c">• Görsel-İşitsel Destek:</text>\n  <text x="48" y="220" font-size="11" fill="#9a3412">Sunumu tablo, grafik ve çok modlu ögelerle destekleme.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">İLETİŞİM ETİĞİ VE ÖZ DEĞERLENDİRME</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#164e63">• Millî-Manevi Değerler ve Hassasiyet:</text>\n  <text x="378" y="108" font-size="11" fill="#155e75">Toplumsal hassasiyet oluşturacak ayrıştırıcı ifadelerden</text>\n  <text x="378" y="124" font-size="11" fill="#155e75">kaçınma; saygı, nezaket ve olumlu değerleri vurgulama.</text>\n  <text x="370" y="148" font-size="11.5" font-weight="bold" fill="#164e63">• Konuşma Sürecini Değerlendirme (TDE3.4):</text>\n  <text x="378" y="164" font-size="11" fill="#155e75">- İçerik, dil, üslup ve beden dilini öz değerlendirme.</text>\n  <text x="378" y="180" font-size="11" fill="#155e75">- Dinleyici (akran/öğretmen) geri bildirimlerini alma.</text>\n  <text x="378" y="196" font-size="11" fill="#155e75">- Özgün konuşmacı kimliği geliştirme ve konuşmayı</text>\n  <text x="378" y="212" font-size="11" font-weight="bold" fill="#0e7490">dijital ortamlar için yeniden düzenleyebilme.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
